const series = $input.item.json.series || [];
let error_rate = 0;
if (series.length > 0 && series[0].pointlist?.length > 0) {
  const lastPoint = series[0].pointlist.slice(-1)[0];
  error_rate = lastPoint[1] || 0;
}
return {
  json: {
    metrics: { error_rate_5m: error_rate, source: 'datadog' },
    raw_alert: $input.item.json
  }
};

const item = $input.item.json;
let repo_file_content = '';
if (typeof item.content === 'string') {
  try { repo_file_content = Buffer.from(item.content, 'base64').toString('utf8'); } catch (e) { repo_file_content = item.content; }
} else if (item.data?.content) {
  try { repo_file_content = Buffer.from(item.data.content, 'base64').toString('utf8'); } catch (e) { repo_file_content = item.data.content; }
} else { repo_file_content = typeof item === 'string' ? item : JSON.stringify(item); }
return { json: { repo_file_content } };

const items = $input.all();
const metricsItem = items.find(i => i.json.metrics) || items[0];
const repoItem = items.find(i => i.json.repo_file_content !== undefined) || items.find(i => i.json.data !== undefined) || items[1] || items[0];
const metrics = metricsItem?.json?.metrics || {};
const raw_alert = metricsItem?.json?.raw_alert || {};
const repo = repoItem?.json?.repo_file_content ?? repoItem?.json?.data ?? '';
const alert = raw_alert.alerts?.[0] || {};
return {
  json: {
    incident: {
      name: alert.labels?.alertname || 'unknown',
      severity: alert.labels?.severity || 'unknown',
      summary: alert.annotations?.summary || '',
      started_at: alert.startsAt || '',
      status: raw_alert.status || ''
    },
    metrics,
    repo_files: { app_py: typeof repo === 'string' ? repo : JSON.stringify(repo) }
  }
};

const raw = $input.item.json;
let ai;
try {
  const text = raw?.candidates?.[0]?.content?.parts?.[0]?.text || raw?.text || '';
  const cleaned = text.replace(/```json\n?|```/g, '').trim();
  ai = JSON.parse(cleaned);
} catch (e) {
  ai = { root_cause: 'Invalid AI output', fix_summary: 'Manual review', patch: '', risk: 'high' };
}
return { json: ai };

const ai = $input.item.json;
if (!ai.patch || ai.risk === 'high') throw new Error('Unsafe patch or high risk');
return { json: { ...ai, branch: 'ai-fix-' + Date.now() } };
